using System.Collections.Generic; public sealed class TimelinePuzzleController:ValidatedPuzzleController { private readonly List<string> cards=new();protected override void ResetPuzzle()=>cards.Clear();public void SetOrder(IEnumerable<string> ids){cards.Clear();if(ids!=null)cards.AddRange(ids);}public bool Submit(string[] expected){if(expected==null||cards.Count!=expected.Length)return false;for(int i=0;i<expected.Length;i++)if(cards[i]!=expected[i])return false;return CompleteWhen(true,string.Join(",",cards));} }
